<template>
  <div class="page-container audit-page">
    <div class="page-head"><div><h2>上报计划审核</h2><p>审核下级提交的逐项明细上报单；本级合计仅作为明细自动汇总展示。</p></div><el-tag type="warning">{{ activeTab === 'pending' ? '待审核' : '已审核' }} {{ filteredRows.length }} 条</el-tag></div>
    <div class="panel"><el-tabs v-model="activeTab" @tab-change="load"><el-tab-pane label="待审核" name="pending" /><el-tab-pane label="已审核" name="history" /></el-tabs><el-form :inline="true"><el-form-item label="关键字"><el-input v-model="filters.keyword" clearable placeholder="上报单号或提交区域" /></el-form-item><el-button type="primary" @click="load">查询</el-button></el-form><el-table :data="filteredRows" border stripe><el-table-column prop="id" label="上报单号" min-width="180" /><el-table-column prop="reporterRegionName" label="提交区域" width="130" /><el-table-column prop="targetLevel" label="上报对象" width="120" /><el-table-column prop="totalArea" label="明细合计（万亩）" width="150" align="right" /><el-table-column prop="submittedAt" label="提交时间" width="120" /><el-table-column label="操作" width="120" fixed="right"><template #default="{row}"><el-button link type="primary" @click="open(row)">审核明细</el-button></template></el-table-column></el-table><el-empty v-if="!rows.length" description="暂无待审核上报单" /></div>
    <el-dialog v-model="visible" title="上报计划审核" width="980px" destroy-on-close><template v-if="current"><el-descriptions :column="4" border><el-descriptions-item label="上报单号">{{ current.id }}</el-descriptions-item><el-descriptions-item label="关联计划">{{ detail.plan?.year }}年{{ detail.plan?.quarter }}{{ detail.plan?.cropType }}</el-descriptions-item><el-descriptions-item label="提交区域">{{ current.reporterRegionName }}</el-descriptions-item><el-descriptions-item label="提交时间">{{ current.submittedAt }}</el-descriptions-item><el-descriptions-item label="上报对象">{{ targetName }}</el-descriptions-item><el-descriptions-item label="明细行数">{{ detail.details?.length || 0 }} 行</el-descriptions-item><el-descriptions-item label="自动汇总">{{ totalArea.toFixed(2) }} 万亩</el-descriptions-item></el-descriptions><div class="detail-title"><b>{{ current.reporterRole === 'town' && userStore.role?.code === 'county' ? '种植主体明细' : '下一级逐项明细' }}</b><span>合计由此表自动计算，不接受仅提交本级汇总</span></div><el-table :data="detail.details" border stripe max-height="380"><el-table-column type="index" label="#" width="55" /><el-table-column prop="childName" label="对象" min-width="190" /><el-table-column prop="childType" label="对象类型" width="120" /><el-table-column prop="cropName" label="作物" width="110" /><el-table-column prop="planArea" label="计划面积（万亩）" width="160" align="right" /><el-table-column prop="remark" label="说明" min-width="180" /></el-table><div v-if="current.reviewComment || current.reviewedAt" class="review-result"><b>审核结果</b><p>处理状态：{{ current.status }}</p><p v-if="current.reviewedAt">处理时间：{{ current.reviewedAt }}</p><p v-if="current.reviewer">处理人：{{ current.reviewer }}</p><p v-if="current.reviewComment">审核意见：{{ current.reviewComment }}</p></div><el-input v-if="canReview(current)" v-model="comment" type="textarea" :rows="3" placeholder="驳回时必须填写审核意见；通过时可选填" class="comment" /></template><template #footer><el-button @click="visible=false">关闭</el-button><template v-if="canReview(current)"><el-button type="danger" @click="review('已驳回')">退回修改</el-button><el-button type="primary" @click="review('已通过')">审核通过</el-button></template></template></el-dialog>
  </div>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { fetchReportAuditList, fetchPlanReportDetail, reviewPlanReport } from '@/api/gpm'
import { REPORT_REVIEWER_BY_ROLE } from '@/mock/gpm/reports'
import { useUserStore } from '@/stores/user'
const userStore = useUserStore(); const rows = ref([]); const activeTab = ref('pending'); const filters = reactive({ keyword: '' }); const visible = ref(false); const current = ref(null); const detail = ref({ details: [] }); const comment = ref('')
const filteredRows = computed(() => rows.value.filter((item) => activeTab.value === 'pending' ? item.status === '待审核' : ['已通过', '已驳回'].includes(item.status)))
const targetName = computed(() => userStore.role?.code === 'county' && current.value?.reporterRole === 'town' ? '乡镇' : ({ county: '县级', town: '乡镇', subject: '种植主体', plot: '地块' }[current.value?.targetLevel] || current.value?.targetLevel || '下一级对象')); const totalArea = computed(() => (detail.value.details || []).reduce((sum, item) => sum + Number(item.planArea || 0), 0))
const canReview = row => !!row && row.status === '待审核' && REPORT_REVIEWER_BY_ROLE[row.reporterRole] === userStore.role?.code
const load = async () => { rows.value = await fetchReportAuditList(userStore.role, filters) }
const open = async (row) => { current.value = row; detail.value = await fetchPlanReportDetail(row.id, userStore.role); comment.value = ''; visible.value = true }
const review = async (action) => { if (action === '已驳回' && !comment.value.trim()) return ElMessage.warning('驳回时必须填写审核意见'); try { await ElMessageBox.confirm(`确认${action === '已通过' ? '通过' : '退回'}该上报单？`, '审核确认') } catch { return }; const result = await reviewPlanReport(current.value.id, action, comment.value, userStore.role); if (!result.success) return ElMessage.error(result.message); ElMessage.success(action === '已通过' ? '审核已通过' : '已退回修改'); visible.value = false; await load() }
onMounted(load)
</script>
<style scoped lang="scss">.audit-page{overflow:auto}.page-head{display:flex;justify-content:space-between;align-items:flex-start}.page-head h2{margin:4px 0}.page-head p,.detail-title span{color:var(--ah-text-secondary);font-size:13px}.audit-page :deep(.el-tabs){margin-bottom:4px}.detail-title{display:flex;justify-content:space-between;margin:18px 0 10px}.comment{margin-top:15px}</style>